  border: 1px solid var(--tiffany-primary);
  border-radius: 16px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  position: relative; /* For hover indicator */
}

.relatedTag:hover,
.relatedTag.focused {
  background-color: var(--tiffany-primary);
  box-shadow: 0 0 0 2px var(--tiffany-dark);
  color: var(--text-primary);
}

.relatedTag::before {
  content: '▲';
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  transition: all 0.2s ease;
  color: var(--tag-success-dark);
  font-size: 0.8rem;
  pointer-events: none;
  z-index: 10;
}

.relatedTag:hover::before,
.relatedTag.focused::before {
  opacity: 1;
  bottom: 140%;
}

/* Autocomplete Popup */
.autocompletePopup {
  position: absolute;
  top: calc(100% - 1px); /* Align top border with input bottom border */
  left: 0;
  right: 0;
  width: 100%;
  z-index: 30; /* Highest z-index */
  background: white;
  border: 1px solid var(--border-light);
  border-top: none;
  margin: 0;
  padding: 0;
}

.suggestionsList {
  list-style: none;
  margin: 0;
  padding: 0.25rem 0;
  max-height: 300px;
  overflow-y: auto;
}

.suggestionItem {
  padding: 0.6rem 1rem;
  cursor: pointer;
  font-size: 0.9rem;
}

.suggestionItem:hover {
  background: var(--bg-card);
}

.suggestionItem.focused {
  background: var(--coral-primary);
  color: white;
}

.suggestionText strong {
  font-weight: 600;
  color: inherit;
