/* CenterPanel 模組樣式 */

.centerPanel {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-main);
  border-right: 1px solid var(--border-color);
}

.panelHeader {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-card);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.panelTitle {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.titleRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.headerControls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
