.studyItem:last-child {
  border-bottom: none;
}

.studyLeft {
  flex-shrink: 0;
  width: 80px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0.5rem;
  font-size: 1.2rem;
  color: var(--text-secondary);
}

.studyNumber {
  font-weight: 600;
}

.citeButton {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 0.2rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.citeButton:hover {
  background-color: var(--bg-card);
  border-color: var(--text-secondary);
}

.studyRight {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding-left: 1rem;
}

.studyTitle {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--coral-primary);
  text-decoration: none;
  line-height: 1.3;
}

.studyTitle:hover {
  text-decoration: underline;
  color: var(--coral-dark);
}

.studyAuthors {
  font-size: 0.9rem;
  color: var(--text-primary);
  margin: 0;
}

.studyMeta {
  font-size: 0.9rem;
  color: var(--text-secondary);
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  margin: 0;
}

.journal {
  font-style: italic;
}

.doiLink {
  color: var(--text-secondary);
  text-decoration: none;
}
.doiLink:hover {
  text-decoration: underline;
}

.studyPmid {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin: 0;
  padding-top: 0.25rem;
}


/* Empty State */
.emptyState {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 2rem;
  text-align: center;
  color: var(--text-secondary);
}

.emptyState p {
  margin: 0;
  font-size: 1rem;
}

/* Loading State */
.loadingContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 1rem;
  color: var(--text-secondary);
}

.spinner {
  width: 40px;
  height: 40px;
  border: 4px solid var(--border-color);
  border-top-color: var(--coral-primary);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

