  transition: all 0.2s;
  font-weight: 500;
  color: var(--text-on-accent);
}

.paginationBtn:hover:not(:disabled) {
  background-color: var(--coral-light);
  border-color: var(--coral-primary);
  color: var(--text-on-accent);
}

.paginationBtn:focus {
  outline: 2px solid var(--coral-dark);
  outline-offset: 2px;
